import React, { useRef } from 'react';

import { Footer, FooterProps, Header, HeaderProps } from './components';
import { TemplateSlidePngCopyAction } from './components/PngCopyAction';
import {
  StyledFlexContainer,
  StyledTemplateContainer,
  StyledTemplateContent,
} from './TemplateSlide.styles';
import { BorderPosition } from './types';
import { getBorderPositionObj } from './utils/getBorderPositionObj';

interface TemplateSlideProps extends Omit<HeaderProps, 'divider'>, FooterProps {
  headerDivider?: boolean;
  children: React.ReactNode;
  dataTestId?: string;
  borderPosition?: BorderPosition[];
  showFootnotes?: boolean;
  backgroundColor?: string;
  enablePngCopy?: boolean;
}

export const TemplateSlide: React.FC<TemplateSlideProps> = ({
  title,
  measure,
  headline,
  period,
  countryId,
  countryId2,
  brandId,
  headerDivider = true,
  footnotes,
  page,
  children,
  dataTestId,
  borderPosition = ['left'],
  showFootnotes = true,
  backgroundColor,
  enablePngCopy = true,
}) => {
  const borderPositionObj = getBorderPositionObj(borderPosition);
  const slideRef = useRef<HTMLDivElement>(null);

  return (
    <StyledTemplateContainer
      ref={slideRef}
      data-testid={dataTestId ? `template-slide-${dataTestId}` : undefined}
      {...borderPositionObj}
      style={{ backgroundColor }}
    >
      <StyledTemplateContent>
        {enablePngCopy && <TemplateSlidePngCopyAction slideRef={slideRef} />}
        <Header
          title={title}
          measure={measure}
          headline={headline}
          period={period}
          countryId={countryId}
          countryId2={countryId2}
          brandId={brandId}
          divider={headerDivider}
        />
        <StyledFlexContainer>{children}</StyledFlexContainer>
        {showFootnotes && <Footer footnotes={footnotes} page={page} />}
      </StyledTemplateContent>
    </StyledTemplateContainer>
  );
};
